    rect(ctx, x + 5, y + 11, 4, 1, '#c75050');
  }
  if (acc === 'sash') {
    rect(ctx, x + 3, y + 8, 8, 2, '#f2c14f');
    rect(ctx, x + 9, y + 12, 2, 2, '#f2c14f');
  }
  if (acc === 'shawl') {
    rect(ctx, x + 2, y + 8, 10, 4, '#b46a8a');
    rect(ctx, x + 2, y + 8, 10, 1, '#d18aa6');
