+  }
+  if (bestNpc) return { kind: 'npc', npc: bestNpc, label: `Talk to ${bestNpc.name}` };
+
+  // Doors
+  let bestDoor = null; bestD = 31;
+  for (const o of map.objects) {
+    if (o.type !== 'building' || !o.door) continue;
+    const d = distTo(o.door.x * TILE + 8, o.door.y * TILE + 10);
