+  // Tillable soil
+  if (game.mapId === 'farm') {
+    const tile = tileAt(map, ft.x, ft.y);
+    if ((tile === T.GRASS || tile === T.DIRT) && !objectAtTile(map, ft.x, ft.y)) {
