+    const d = distTo(o.x * TILE + 8, (o.y + 1) * TILE - 4);
+    if (d < bestD) { bestD = d; bestChop = o; }
+  }
+  if (bestChop) {
+    const label = bestChop.type === 'rock' ? 'Mine rock' : 'Chop wood';
