+}
+
+/* ------------------------------------------------------------------ */
+/* Actions                                                            */
+/* ------------------------------------------------------------------ */
+function doAction() {
+  if (mode !== 'playing' || transitioning) return;
+  unlockAudio();
+  if (overlayStack.length) {
+    const top = overlayStack[overlayStack.length - 1];
