+}
+
+function finishFishing(success, reason) {
+  if (!fishing) return;
+  fishing.phase = 'result';
+  fishing.resultTimer = 1.3;
+  fishing.result = success ? fishing.result : null;
+  $('catch-bar').style.visibility = 'hidden';
+  $('fish-hook').textContent = '…';
