+  game.npcFriends[npc.id] = clamp(friendship(npc.id) + gain, 0, 100);
+  npc.talkedToday = true;
+  game.stats.talks = (game.stats.talks || 0) + 1;
+  if (npc.id === 'mayor' && !game.stats.talkedMayor) {
+    game.stats.talkedMayor = true;
