+  }
+  $('inv-money').textContent = `${game.money.toLocaleString()}g`;
+}
+
+function handleInventoryItem(id) {
+  const item = ITEMS[id];
+  if (!item) return;
+  if (item.kind === 'seed') {
+    game.seed = id;
+    game.tool = 'seeds';
+    renderHotbar();
+    renderInventory();
+    toast(`Seed pouch now holds ${item.name}.`, item.icon, 'good');
+    sfx('click');
+    return;
+  }
+  if (item.energy) {
+    if (game.energy >= game.maxEnergy) { toast('You are already full of energy.', '⚡'); return; }
+    removeItem(id, 1);
+    const gained = restoreEnergy(item.energy);
+    toast(`Ate ${item.name}. +${gained} energy.`, item.icon, 'good');
+    sfx('harvest');
+    renderInventory();
+    return;
+  }
+  toast(`${item.name}: ${item.desc || 'A useful thing.'}`, item.icon);
+  sfx('click');
+}
+
+/* ------------------------------------------------------------------ */
+/* Menu, creation and UI bindings                                     */
+/* ------------------------------------------------------------------ */
+function refreshCreationUI() {
+  const segs = [['gender-opts', 'gender'], ['style-opts', 'style']];
+  for (const [hostId, field] of segs) {
+    const host = $(hostId);
+    if (!host) continue;
+    for (const btn of host.querySelectorAll('button')) {
+      btn.classList.toggle('active', btn.dataset.value === selectedCreation[field]);
+    }
+  }
+  for (const [hostId, field, palette] of [
+    ['skin-opts', 'skin', PALETTES.skin],
+    ['hair-opts', 'hair', PALETTES.hair],
+    ['shirt-opts', 'shirt', PALETTES.shirt],
+  ]) {
+    const host = $(hostId);
+    if (!host) continue;
+    for (const btn of host.querySelectorAll('button')) {
+      btn.classList.toggle('active', btn.dataset.value === selectedCreation[field]);
+    }
+  }
+  const label = $('preview-label');
+  if (label) label.textContent = selectedCreation.name ? `${selectedCreation.name}'s look` : 'Ready for the valley';
+}
+
+function initCreationUI() {
+  for (const [hostId, field] of [['gender-opts', 'gender'], ['style-opts', 'style']]) {
+    const host = $(hostId);
+    if (!host) continue;
+    host.addEventListener('click', (e) => {
+      const btn = e.target.closest('button[data-value]');
+      if (!btn) return;
+      selectedCreation[field] = btn.dataset.value;
+      refreshCreationUI();
+      sfx('click');
+    });
+  }
+  const swatchDefs = [
+    ['skin-opts', 'skin', PALETTES.skin],
+    ['hair-opts', 'hair', PALETTES.hair],
+    ['shirt-opts', 'shirt', PALETTES.shirt],
+  ];
+  for (const [hostId, field, colors] of swatchDefs) {
+    const host = $(hostId);
+    if (!host) continue;
+    host.innerHTML = colors.map(c => `<button class="swatch" data-value="${c}" style="--sw:${c}" aria-label="${c}"></button>`).join('');
+    host.addEventListener('click', (e) => {
+      const btn = e.target.closest('button[data-value]');
+      if (!btn) return;
+      selectedCreation[field] = btn.dataset.value;
+      refreshCreationUI();
+      sfx('click');
+    });
+  }
+  const nameInput = $('farmer-name');
+  if (nameInput) {
+    nameInput.addEventListener('input', () => {
+      selectedCreation.name = nameInput.value.trim().slice(0, 14);
+      refreshCreationUI();
+    });
+  }
+  $('btn-create-back').addEventListener('click', () => {
+    $('creation').classList.add('hidden');
+    $('menu').classList.remove('hidden');
+    mode = 'menu';
+    sfx('close');
+  });
+  $('btn-start').addEventListener('click', startNewGame);
+  refreshCreationUI();
+}
+
+function bindUI() {
+  $('btn-new').addEventListener('click', () => {
+    unlockAudio();
+    mode = 'creation';
+    $('menu').classList.add('hidden');
+    $('creation').classList.remove('hidden');
+    const nameInput = $('farmer-name');
+    if (nameInput) nameInput.value = selectedCreation.name === 'Farmer' ? 'Farmer' : selectedCreation.name;
+    refreshCreationUI();
+    sfx('open');
+  });
+  $('btn-continue').addEventListener('click', continueGame);
+  $('btn-how').addEventListener('click', openHelp);
+  $('btn-inventory').addEventListener('click', openInventory);
+  $('btn-help').addEventListener('click', openHelp);
+  $('btn-menu').addEventListener('click', openPause);
+  $('btn-sound').addEventListener('click', () => {
+    unlockAudio();
+    soundOn = !soundOn;
+    setMuted(!soundOn);
+    updateSoundButton();
+    if (soundOn) sfx('click');
+  });
+
+  $('inv-close').addEventListener('click', () => closeOverlay('inventory'));
+  $('help-close').addEventListener('click', () => closeOverlay('help'));
+  $('help-ok').addEventListener('click', () => closeOverlay('help'));
+
+  $('dlg-next').addEventListener('click', nextDialogue);
+  $('dlg-gift').addEventListener('click', giveGift);
+  $('dlg-close').addEventListener('click', () => closeOverlay('dialogue'));
+
+  $('shop-close').addEventListener('click', () => closeOverlay('shop'));
+  $('shop-tabs').addEventListener('click', (e) => {
+    const btn = e.target.closest('button[data-tab]');
+    if (!btn || !activeShop) return;
+    activeShop.tab = btn.dataset.tab;
+    renderShop();
+    sfx('click');
+  });
+  $('shop-grid').addEventListener('click', (e) => {
+    const btn = e.target.closest('button[data-buy], button[data-animal], button[data-sell], button[data-shipall], button[data-service]');
+    if (!btn || !activeShop) return;
+    if (btn.dataset.buy) buyItem(btn.dataset.buy);
+    else if (btn.dataset.animal) buyAnimal(btn.dataset.animal);
+    else if (btn.dataset.sell) sellItem(btn.dataset.sell, Number(btn.dataset.qty) || 1);
+    else if (btn.dataset.shipall) shipAll();
+    else if (btn.dataset.service) doService(btn.dataset.service);
+  });
+
+  $('inv-grid').addEventListener('click', (e) => {
+    const btn = e.target.closest('button[data-inv]');
+    if (btn) handleInventoryItem(btn.dataset.inv);
+  });
+  $('hotbar').addEventListener('click', (e) => {
+    const btn = e.target.closest('button[data-tool]');
+    if (btn) selectTool(btn.dataset.tool);
+  });
+  $('fish-hook').addEventListener('click', fishingPress);
+
+  $('pause-resume').addEventListener('click', () => closeOverlay('pause'));
+  $('pause-save').addEventListener('click', () => saveGame(true));
+  $('pause-help').addEventListener('click', openHelp);
+  $('pause-quit').addEventListener('click', () => {
+    saveGame(false);
+    returnToMenu();
+  });
+  $('day-overlay').addEventListener('click', () => {
+    if (overlayStack.includes('day-overlay')) closeOverlay('day-overlay');
+  });
+
+  // close overlays by clicking the dim background (but not the card)
+  for (const id of ['dialogue', 'shop', 'inventory', 'help', 'pause']) {
+    const el = $(id);
+    if (!el) continue;
+    el.addEventListener('pointerdown', (e) => {
+      if (e.target === el) closeOverlay(id);
+    });
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Boot                                                               */
+/* ------------------------------------------------------------------ */
+function boot() {
+  initMuted();
+  soundOn = !isMuted();
+  updateSoundButton();
+  maps = buildMaps();
+  caches = {};
+  for (const key of Object.keys(maps)) caches[key] = buildMapCache(maps[key]);
+  demo = createDemoState();
+  if (isTouch) document.body.classList.add('touch');
+  resize();
+  bindInput();
+  bindTouch();
+  bindUI();
+  initCreationUI();
+  updateContinueButton();
+  updateSoundButton();
+  $('hud').classList.add('hidden');
+  $('menu').classList.remove('hidden');
+  mode = 'menu';
+  camera = { ...demoCam };
+  requestAnimationFrame(loop);
+}
+
+boot();

input.content:
:root {
  --ink: #33251b;
  --ink-deep: #20160f;
  --cream: #fbf0d4;
  --cream-2: #f0dfb6;
  --cream-3: #e2c98f;
  --wood: #7b4a2e;
  --wood-dark: #4a2c1a;
  --gold: #f2c14f;
  --gold-deep: #b98524;
  --green: #5c9e46;
  --green-dark: #37682c;
  --red: #c75050;
  --panel-shadow: 0 0 0 3px #f8eccb, 0 0 0 6px #3b2a1e, 0 8px 0 rgba(0, 0, 0, .28), inset 0 0 0 2px #fff8e3;
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden;
  background: #172114;
  font-family: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  color: var(--ink);
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}
button { font-family: inherit; color: inherit; cursor: pointer; }
.hidden { display: none !important; }
.muted { opacity: .7; }
.small-note { font-size: 12px; margin-top: 10px; text-align: center; }

#game-shell {
  position: fixed; inset: 0; overflow: hidden;
  background: #172114;
}
#game {
  width: 100%; height: 100%; display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  touch-action: none;
}
#vignette {
  position: absolute; inset: 0; z-index: 2; pointer-events: none;
  background: radial-gradient(ellipse at center, rgba(0,0,0,0) 52%, rgba(8,14,6,.38) 100%);
  box-shadow: inset 0 0 90px rgba(8,14,6,.35);
}

/* ---------- Shared pixel panels ---------- */
.panel {
  background: linear-gradient(180deg, #fdf4dc 0%, var(--cream) 35%, var(--cream-2) 100%);
  border: 3px solid var(--wood-dark);
  border-radius: 4px;
  box-shadow: var(--panel-shadow);
  color: var(--ink);
}
.panel-title {
  font-family: "Courier New", monospace;
  font-weight: 900; font-size: 12px; letter-spacing: 2px; text-transform: uppercase;
  color: var(--wood-dark); margin-bottom: 5px;
}
.big-btn {
  display: block; width: 100%;
  padding: 13px 18px;
  font-family: "Courier New", monospace;
  font-size: 15px; font-weight: 900; letter-spacing: 1.5px; text-transform: uppercase;
  background: linear-gradient(180deg, #f9e8bd, #e7cc90);
  border: 3px solid var(--wood-dark);
  border-radius: 3px;
  box-shadow: 0 0 0 3px #f7e8c2, 0 5px 0 #5a3a23, 0 8px 12px rgba(0,0,0,.25);
  transition: transform .08s, box-shadow .08s, filter .12s;
}
.big-btn:hover { filter: brightness(1.06); }
.big-btn:active { transform: translateY(4px); box-shadow: 0 0 0 3px #f7e8c2, 0 1px 0 #5a3a23; }
.big-btn.primary {
  background: linear-gradient(180deg, #ffe47e, #f2c14f 60%, #dba52e);
  color: #3b2812;
  box-shadow: 0 0 0 3px #ffeeb0, 0 5px 0 #8f5f18, 0 8px 12px rgba(0,0,0,.25);
}
.big-btn.small { font-size: 12px; padding: 10px 14px; }
.big-btn.danger { background: linear-gradient(180deg, #e9b7a8, #cc7a68); }
.big-btn.disabled, .big-btn:disabled, .chip-btn:disabled, .chip-btn.disabled {
  opacity: .46; cursor: not-allowed; filter: saturate(.5);
}
.chip-btn {
  font-family: "Courier New", monospace;
  font-size: 11px; font-weight: 900; letter-spacing: .5px;
  padding: 7px 11px;
  background: linear-gradient(180deg, #fdf2d2, #e8d19c);
  border: 2px solid var(--wood-dark);
  border-radius: 3px;
  box-shadow: 0 2px 0 #6b4526;
  color: var(--ink);
  transition: transform .06s;
}
.chip-btn:active { transform: translateY(2px); box-shadow: none; }
.chip-btn.primary { background: linear-gradient(180deg, #ffe989, #efbd45); }
.chip-btn.ghost { background: transparent; box-shadow: none; border-color: rgba(59,42,30,.45); }
.corner-close {
  position: absolute; top: -14px; right: -14px;
  width: 38px; height: 38px; border-radius: 50%;
  border: 3px solid var(--wood-dark);
  background: linear-gradient(180deg, #fdf2d2, #e5c98e);
  color: var(--wood-dark);
  font-weight: 900; font-size: 17px;
  box-shadow: 0 3px 0 #5a3a23, 0 0 0 3px #f8eccb;
  z-index: 5;
}
.corner-close:active { transform: translateY(3px); box-shadow: none; }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 6; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button, #hud .panel, #hotbar { pointer-events: auto; }

#hud-left {
  position: absolute;
  top: calc(12px + env(safe-area-inset-top, 0px));
  left: calc(12px + env(safe-area-inset-left, 0px));
  width: 286px; max-width: calc(100vw - 150px);
  display: flex; flex-direction: column; gap: 10px;
}
.status-panel { padding: 10px 12px 11px; }
.date-row {
  display: flex; align-items: center; gap: 8px;
  font-family: "Courier New", monospace; font-weight: 900; font-size: 14px; letter-spacing: .5px;
}
#hud-season { color: #84602c; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; }
#hud-weather { margin-left: auto; font-size: 18px; filter: drop-shadow(0 1px 0 #fff8e3); }
.clock-row {
  display: flex; align-items: baseline; gap: 8px;
  margin-top: 2px; font-family: "Courier New", monospace;
}
#hud-clock { font-size: 18px; font-weight: 900; color: #5c3d22; }
#hud-location { font-size: 10px; text-transform: uppercase; letter-spacing: .7px; color: #84602c; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.money-row {
  margin-top: 5px; display: flex; align-items: baseline; gap: 4px;
  font-family: "Courier New", monospace; font-size: 14px;
}
.money-row .coin { color: var(--gold-deep); font-size: 11px; }
.money-row b { font-size: 17px; color: #6d4a1c; }
.money-row .g { font-size: 11px; color: #9b763c; }
.energy-row { display: flex; align-items: center; gap: 6px; margin-top: 6px; }
.energy-row .bolt { font-size: 12px; }
.energy-bar {
  flex: 1; height: 11px; background: #3d2b1b; border: 2px solid #3d2b1b; border-radius: 2px;
  overflow: hidden; box-shadow: inset 0 2px 0 rgba(0,0,0,.2);
}
.energy-bar i {
  display: block; height: 100%; width: 100%;
  background: linear-gradient(180deg, #a8e46a, #5fae3e);
  border-right: 2px solid rgba(255,255,255,.35);
  transition: width .25s;
}
#hud-energy-text { font-family: "Courier New", monospace; font-size: 10px; font-weight: 900; color: #6d4a1c; min-width: 44px; text-align: right; }
#quest-card { padding: 9px 12px 10px; }
#quest-text { font-size: 12.5px; line-height: 1.35; font-weight: 600; }
#quest-reward { margin-top: 4px; font-size: 10px; font-family: "Courier New", monospace; color: #9b6a24; letter-spacing: .5px; }

#hud-right {
  position: absolute;
  top: calc(12px + env(safe-area-inset-top, 0px));
  right: calc(12px + env(safe-area-inset-right, 0px));
  display: flex; gap: 7px;
}
.icon-btn {
  width: 42px; height: 42px;
  border: 3px solid var(--wood-dark);
  border-radius: 4px;
  background: linear-gradient(180deg, #fdf2d2, #e5c98e);
  box-shadow: 0 0 0 3px #f8eccb, 0 3px 0 #5a3a23;
  font-size: 18px; font-weight: 900;
  display: grid; place-items: center;
  transition: transform .06s;
}
.icon-btn:active { transform: translateY(3px); box-shadow: 0 0 0 3px #f8eccb; }
.icon-btn.muted { filter: grayscale(1); opacity: .7; }

#prompt {
  position: absolute; left: 50%; bottom: 108px; transform: translateX(-50%);
  background: rgba(30, 22, 14, .88);
  color: #fdf3d8;
  border: 2px solid #f2c14f;
  border-radius: 4px;
  padding: 7px 13px;
  font-family: "Courier New", monospace;
  font-size: 12px; font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 3px 0 rgba(0,0,0,.35);
  z-index: 7;
}
.keycap {
  display: inline-grid; place-items: center;
  min-width: 20px; height: 19px; padding: 0 5px; margin-right: 5px;
  border-radius: 3px; background: #f2c14f; color: #35230f;
  font-weight: 900; font-size: 11px;
  box-shadow: inset 0 -2px 0 rgba(0,0,0,.25);
}

#toasts {
  position: absolute; top: calc(14px + env(safe-area-inset-top, 0px)); left: 50%;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  z-index: 80; pointer-events: none;
}
.toast {
  display: flex; align-items: center; gap: 8px;
  background: rgba(28, 21, 13, .92);
  border: 2px solid #e7c97f;
  color: #fdf3d8;
  padding: 7px 13px;
  border-radius: 4px;
  font-size: 12.5px; font-weight: 700;
  box-shadow: 0 3px 0 rgba(0,0,0,.3);
  opacity: 0; transform: translateY(-8px);
  transition: opacity .25s, transform .25s;
  max-width: min(520px, 90vw);
  text-align: center;
}
.toast.show { opacity: 1; transform: translateY(0); }
.toast .t-icon { font-size: 15px; }
.toast.good { border-color: #a9d47a; }
.toast.bad { border-color: #e28a7a; }
.toast.quest { border-color: #f2c14f; box-shadow: 0 0 12px rgba(242,193,79,.35), 0 3px 0 rgba(0,0,0,.3); }

/* ---------- Hotbar ---------- */
#hotbar {
  position: absolute; left: 50%; bottom: calc(12px + env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%);
  display: flex; align-items: flex-end; gap: 5px;
  padding: 7px 9px;
  background: rgba(30, 22, 14, .86);
  border: 3px solid #d9b96f;
  border-radius: 5px;
  box-shadow: 0 0 0 3px rgba(28,20,11,.8), 0 5px 0 rgba(0,0,0,.3);
  z-index: 8;
}
.hot-slot {
  width: 58px; height: 64px;
  position: relative;
  background: linear-gradient(180deg, #f6e7c0, #d9bf87);
  border: 2px solid #4a2c1a;
  border-radius: 3px;
  box-shadow: inset 0 2px 0 rgba(255,255,255,.55), inset 0 -3px 0 rgba(120,80,40,.22);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  color: #4a2c1a;
  transition: transform .06s, filter .1s;
}
.hot-slot:hover { filter: brightness(1.07); }
.hot-slot.active {
  background: linear-gradient(180deg, #ffeaa2, #f2c14f);
  border-color: #fff4c4;
  box-shadow: 0 0 0 2px #f2c14f, 0 0 14px rgba(242,193,79,.5), inset 0 2px 0 rgba(255,255,255,.6);
  transform: translateY(-3px);
}
.hot-key {
  position: absolute; top: 2px; left: 4px;
  font-family: "Courier New", monospace; font-size: 9px; font-weight: 900; opacity: .6;
}
.hot-icon { font-size: 22px; line-height: 1; filter: drop-shadow(0 1px 0 rgba(255,255,255,.5)); }
.hot-name {
  font-size: 8px; font-weight: 900; letter-spacing: .3px; text-transform: uppercase;
  max-width: 54px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: "Courier New", monospace;
}
.hot-count {
  position: absolute; right: 3px; bottom: 3px;
  min-width: 16px; padding: 1px 4px;
  background: #3b2a1e; color: #ffe9a8;
  font-family: "Courier New", monospace; font-size: 9px; font-weight: 900;
  border-radius: 8px; text-align: center;
}
.hot-hint {
  writing-mode: vertical-rl;
  font-family: "Courier New", monospace; font-size: 8px; letter-spacing: 1px;
  color: #d9c69a; opacity: .7; padding: 2px 0 3px 2px; height: 58px;
}

/* ---------- Overlays ---------- */
.overlay {
  position: fixed; inset: 0; z-index: 40;
  display: flex; align-items: center; justify-content: center;
  padding: 18px;
  background: rgba(12, 19, 12, .6);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}
.overlay > * { animation: pop .16s ease-out; }
@keyframes pop { from { transform: scale(.96); opacity: .5; } to { transform: scale(1); opacity: 1; } }

/* Title */
.menu-overlay {
  flex-direction: column; justify-content: center; gap: 30px;
  background:
    linear-gradient(180deg, rgba(10,17,12,.64) 0%, rgba(10,17,12,.18) 38%, rgba(10,17,12,.82) 100%);
  z-index: 20;
  backdrop-filter: none;
}
.menu-shade {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at 50% 42%, rgba(255,236,160,.08), transparent 58%);
}
.title-block { position: relative; text-align: center; z-index: 1; animation: floatIn .55s ease-out; }
@keyframes floatIn { from { opacity: 0; transform: translateY(-14px); } to { opacity: 1; transform: none; } }
.title-kicker {
  font-family: "Courier New", monospace; font-size: 11px; font-weight: 700;
  letter-spacing: 4px; text-transform: uppercase; color: #d9ecc0;
  text-shadow: 0 2px 0 rgba(0,0,0,.5); margin-bottom: 8px;
}
.title-block h1 {
  margin: 0;
  font-family: "Courier New", monospace;
  font-size: clamp(44px, 9vw, 92px);
  line-height: .95;
  letter-spacing: -.02em;
  color: #ffe27a;
  text-shadow:
    0 4px 0 #c4772e,
    0 8px 0 #8e4c20,
    0 12px 0 #58301a,
    0 18px 22px rgba(0,0,0,.55);
  -webkit-text-stroke: 2px #4a2c1a;
}
.title-sub {
  margin-top: 16px;
  font-family: "Courier New", monospace; font-size: 11px; font-weight: 900;
  letter-spacing: 5px; color: #f5e8c8; text-shadow: 0 2px 0 rgba(0,0,0,.5);
}
.menu-buttons { position: relative; z-index: 1; width: min(320px, 88vw); display: flex; flex-direction: column; gap: 13px; }
.menu-footer {
  position: absolute; bottom: calc(16px + env(safe-area-inset-bottom, 0px)); left: 0; right: 0;
  display: flex; justify-content: center; gap: 22px; flex-wrap: wrap;
  font-family: "Courier New", monospace; font-size: 10px; letter-spacing: 1px;
  color: rgba(245,232,200,.7);
}

/* Creation */
#creation { z-index: 25; }
.creation-card { width: min(780px, 96vw); max-height: 94vh; overflow: auto; padding: 20px 22px 22px; position: relative; }
