.create-layout { display: grid; grid-template-columns: 190px 1fr; gap: 22px; align-items: start; }
.preview-wrap { display: flex; flex-direction: column; align-items: center; gap: 8px; }
#preview {
  width: 168px; height: 216px; image-rendering: pixelated;
  border: 3px solid #4a2c1a; border-radius: 3px;
