}
#farmer-name:focus { border-color: #c98a2e; box-shadow: 0 0 0 3px rgba(242,193,79,.4); }
.segmented { display: flex; gap: 6px; flex-wrap: wrap; }
.segmented button {
  flex: 1; min-width: 86px; padding: 8px 10px;
  font-family: "Courier New", monospace; font-size: 11px; font-weight: 900; letter-spacing: .5px;
  background: #efe0b8; border: 2px solid #6b4526; border-radius: 3px;
  box-shadow: 0 2px 0 #6b4526;
  color: #5a3a23;
}
.segmented button.active { background: linear-gradient(180deg, #ffe989, #efbd45); border-color: #4a2c1a; color: #3b2812; transform: translateY(-1px); }
.swatch-row { display: flex; align-items: center; gap: 10px; }
.swatch-row .field-label { margin: 0; min-width: 52px; }
.swatches { display: flex; gap: 7px; flex-wrap: wrap; }
.swatch {
  width: 30px; height: 30px; border-radius: 50%;
  background: var(--sw);
  border: 2px solid #4a2c1a;
  box-shadow: 0 2px 0 rgba(74,44,26,.35), inset 0 2px 0 rgba(255,255,255,.3);
  transition: transform .08s;
}
.swatch.active { outline: 3px solid #f2c14f; outline-offset: 2px; transform: translateY(-2px); }
.start-btn { margin-top: 10px; }

/* Dialogue */
#dialogue { z-index: 44; }
.dialogue-card {
  width: min(720px, 96vw); padding: 18px; display: flex; gap: 16px; align-items: flex-start;
  position: relative;
}
.portrait-wrap {
  flex: 0 0 128px; width: 128px; height: 128px;
  border: 3px solid #4a2c1a; border-radius: 3px; overflow: hidden;
  box-shadow: 0 0 0 3px #f8eccb;
}
#portrait { width: 100%; height: 100%; image-rendering: pixelated; display: block; }
.dialogue-body { flex: 1; min-width: 0; }
.dialogue-name { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; font-family: "Courier New", monospace; font-weight: 900; font-size: 17px; color: #4a2c1a; }
#dlg-role { font-size: 10px; letter-spacing: 1px; text-transform: uppercase; color: #9b6a24; }
.hearts { color: #d5476d; font-size: 14px; letter-spacing: 3px; margin: 3px 0 6px; text-shadow: 0 1px 0 #fff; }
#dlg-text { margin: 4px 0 14px; font-size: 14.5px; line-height: 1.45; min-height: 52px; color: #3b2a1e; }
.dialogue-actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* Shop */
#shop { z-index: 46; }
.shop-card { width: min(900px, 96vw); max-height: 90vh; padding: 18px 20px; display: flex; flex-direction: column; position: relative; }
.shop-head { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.shop-icon { font-size: 38px; filter: drop-shadow(0 2px 0 rgba(0,0,0,.15)); }
.shop-head h2 { margin: 0; }
#shop-tagline { font-size: 12px; color: #84602c; }
.shop-money { margin-left: auto; font-family: "Courier New", monospace; font-weight: 900; font-size: 16px; color: #6d4a1c; }
.shop-money .coin { color: var(--gold-deep); font-size: 11px; }
.shop-tabs { display: flex; gap: 6px; margin-bottom: 10px; border-bottom: 2px solid rgba(90,58,35,.2); padding-bottom: 8px; }
.shop-tabs button {
  padding: 7px 16px; border: 2px solid #6b4526; border-radius: 3px;
  background: #efe0b8; font-family: "Courier New", monospace; font-size: 11px; font-weight: 900;
  letter-spacing: 1px; text-transform: uppercase; color: #6b4526;
  box-shadow: 0 2px 0 #6b4526;
}
.shop-tabs button.active { background: linear-gradient(180deg, #ffe989, #efbd45); color: #3b2812; border-color: #4a2c1a; }
.shop-grid { flex: 1; overflow-y: auto; min-height: 120px; max-height: 58vh; padding: 4px 6px 8px 2px; display: flex; flex-direction: column; gap: 8px; }
.shop-section-title { font-family: "Courier New", monospace; font-size: 10px; font-weight: 900; letter-spacing: 2px; text-transform: uppercase; color: #9b6a24; margin: 5px 2px 1px; }
.shop-item {
  display: flex; align-items: center; gap: 12px;
  background: rgba(255,250,235,.7);
  border: 2px solid rgba(90,58,35,.32);
  border-radius: 3px;
  padding: 9px 12px;
}
.shop-item-icon { font-size: 30px; width: 42px; text-align: center; flex: 0 0 42px; }
.shop-item-body { flex: 1; min-width: 0; }
.shop-item-name { font-family: "Courier New", monospace; font-size: 13px; font-weight: 900; color: #4a2c1a; }
.owned { font-family: "Trebuchet MS", sans-serif; font-size: 10px; font-weight: 600; color: #9b6a24; margin-left: 6px; }
.shop-item-desc { font-size: 11.5px; line-height: 1.35; color: #6f5635; margin-top: 2px; }
.shop-item-buy { flex: 0 0 auto; text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.price { font-family: "Courier New", monospace; font-size: 12px; font-weight: 900; color: #7a4f17; }
.sell-btns { display: flex; gap: 5px; flex-wrap: wrap; justify-content: flex-end; }
.ship-banner {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  background: linear-gradient(180deg, #e6f2cf, #cfe3ab);
  border: 2px solid #5c8a3c; border-radius: 3px;
  padding: 10px 13px; font-size: 12px;
}
.ship-banner span { color: #5f6b3f; font-size: 11px; }
.empty-shop { padding: 24px; text-align: center; font-size: 13px; color: #7a6242; }
.shop-hint { font-size: 11px; line-height: 1.4; color: #6f5635; margin-top: 9px; padding: 7px 10px; background: rgba(90,58,35,.08); border-left: 3px solid #c99a44; border-radius: 2px; }

/* Inventory */
#inventory { z-index: 45; }
.inventory-card { width: min(760px, 96vw); max-height: 90vh; padding: 20px; display: flex; flex-direction: column; position: relative; }
.inv-sub { font-size: 12px; color: #7a5c35; margin: -6px 0 12px; line-height: 1.4; }
.inv-grid { overflow-y: auto; max-height: 56vh; display: grid; grid-template-columns: repeat(auto-fill, minmax(142px, 1fr)); gap: 9px; padding: 2px 4px 8px 2px; }
.inv-card {
  position: relative; text-align: left;
  display: grid; grid-template-columns: 36px 1fr; grid-template-rows: auto auto auto; gap: 1px 7px;
  padding: 9px 10px; border: 2px solid rgba(90,58,35,.35); border-radius: 3px;
  background: rgba(255,250,235,.75); color: #4a2c1a;
}
.inv-card:hover { border-color: #c98a2e; background: #fff8e4; }
.inv-card.selected { border-color: #c98a2e; box-shadow: 0 0 0 2px #f2c14f inset; background: #fff4cf; }
.inv-icon { grid-row: span 2; font-size: 28px; align-self: center; text-align: center; }
.inv-name { font-family: "Courier New", monospace; font-size: 11.5px; font-weight: 900; line-height: 1.2; }
.inv-count { position: absolute; top: 7px; right: 8px; font-family: "Courier New", monospace; font-size: 11px; font-weight: 900; color: #7a4f17; }
.inv-tip { font-size: 9.5px; line-height: 1.25; color: #8b6b42; grid-column: 2; }
.inv-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 10px; font-family: "Courier New", monospace; font-size: 11px; font-weight: 900; color: #7a4f17; }
#inv-hint { font-weight: 400; color: #9b7a4c; }

/* Fishing */
#fishing { z-index: 47; }
.fishing-card { width: min(430px, 94vw); padding: 18px 20px 20px; text-align: center; }
.fish-title { font-family: "Courier New", monospace; font-size: 18px; font-weight: 900; color: #3b2a1e; }
.fish-sub { font-size: 12px; color: #7a5c35; margin-top: 4px; }
.fish-scene { margin: 12px auto 10px; width: 100%; border: 3px solid #4a2c1a; border-radius: 3px; overflow: hidden; background: #35506b; }
#fish-canvas { width: 100%; height: auto; display: block; image-rendering: pixelated; }
.catch-bar {
  position: relative; height: 28px; margin: 0 4px 12px;
  background: #3d2b1b; border: 3px solid #4a2c1a; border-radius: 3px;
  overflow: hidden;
  box-shadow: inset 0 2px 0 rgba(0,0,0,.35);
}
.catch-bar::before {
  content: ""; position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, rgba(255,255,255,.07) 0 2px, transparent 2px 20px);
}
.catch-zone {
  position: absolute; top: 0; bottom: 0; width: 26%; left: 30%;
  background: linear-gradient(180deg, #a8e46a, #4f9a3e);
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.25);
}
.catch-marker {
  position: absolute; top: -2px; bottom: -2px; width: 4px; left: 0;
  background: #fff3b0; box-shadow: 0 0 8px #fff3b0, 0 0 2px #3b2a1e;
  transform: translateX(-2px);
  z-index: 2;
}
.fish-timer { height: 7px; background: #3d2b1b; border: 2px solid #4a2c1a; border-radius: 2px; overflow: hidden; margin-top: 4px; }
#fish-timer-fill { display: block; height: 100%; width: 100%; background: linear-gradient(180deg, #ffd76a, #e8a12e); transition: width .05s linear; }

/* Help */
#help { z-index: 48; }
.help-card { width: min(880px, 96vw); max-height: 92vh; overflow-y: auto; padding: 22px; position: relative; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 16px; }
.help-grid h3 { margin: 0 0 6px; font-family: "Courier New", monospace; font-size: 13px; letter-spacing: 1px; color: #6d4a1c; text-transform: uppercase; }
.help-grid p { margin: 0 0 9px; font-size: 12.5px; line-height: 1.5; color: #4a3826; }
.help-grid b { color: #3b2a1e; }
