.day-card { text-align: center; color: #fdf3d8; animation: dayIn .45s ease-out; }
@keyframes dayIn { from { opacity: 0; transform: translateY(18px) scale(.97); } to { opacity: 1; transform: none; } }
.day-kicker { font-family: "Courier New", monospace; font-size: 11px; letter-spacing: 4px; text-transform: uppercase; color: #d9ecc0; }
.day-card h2 { margin: 6px 0 10px; font-family: "Courier New", monospace; font-size: clamp(40px, 8vw, 72px); color: #ffe27a; text-shadow: 0 4px 0 #8e4c20, 0 8px 16px rgba(0,0,0,.5); }
.day-weather { font-size: 18px; font-weight: 700; margin-bottom: 14px; }
.day-summary { display: flex; flex-direction: column; gap: 5px; font-size: 12.5px; color: #e9dcbc; max-width: 420px; margin: 0 auto; }

