  position: fixed; right: calc(24px + env(safe-area-inset-right, 0px));
  bottom: calc(34px + env(safe-area-inset-bottom, 0px));
  width: 86px; height: 86px; border-radius: 50%;
  border: 4px solid #4a2c1a;
  background: radial-gradient(circle at 38% 32%, #fff2a4, #f2c14f 58%, #d69a26);
