.inventory-card { width: min(760px, 96vw); max-height: 90vh; padding: 20px; display: flex; flex-direction: column; position: relative; }
.inv-sub { font-size: 12px; color: #7a5c35; margin: -6px 0 12px; line-height: 1.4; }
.inv-grid { overflow-y: auto; max-height: 56vh; display: grid; grid-template-columns: repeat(auto-fill, minmax(142px, 1fr)); gap: 9px; padding: 2px 4px 8px 2px; }
.inv-card {
  position: relative; text-align: left;
  display: grid; grid-template-columns: 36px 1fr; grid-template-rows: auto auto auto; gap: 1px 7px;
  padding: 9px 10px; border: 2px solid rgba(90,58,35,.35); border-radius: 3px;
  background: rgba(255,250,235,.75); color: #4a2c1a;
}
.inv-card:hover { border-color: #c98a2e; background: #fff8e4; }
.inv-card.selected { border-color: #c98a2e; box-shadow: 0 0 0 2px #f2c14f inset; background: #fff4cf; }
.inv-icon { grid-row: span 2; font-size: 28px; align-self: center; text-align: center; }
.inv-name { font-family: "Courier New", monospace; font-size: 11.5px; font-weight: 900; line-height: 1.2; }
.inv-count { position: absolute; top: 7px; right: 8px; font-family: "Courier New", monospace; font-size: 11px; font-weight: 900; color: #7a4f17; }
.inv-tip { font-size: 9.5px; line-height: 1.25; color: #8b6b42; grid-column: 2; }
.inv-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 10px; font-family: "Courier New", monospace; font-size: 11px; font-weight: 900; color: #7a4f17; }
#inv-hint { font-weight: 400; color: #9b7a4c; }

/* Fishing */
#fishing { z-index: 47; }
.fishing-card { width: min(430px, 94vw); padding: 18px 20px 20px; text-align: center; }
.fish-title { font-family: "Courier New", monospace; font-size: 18px; font-weight: 900; color: #3b2a1e; }
.fish-sub { font-size: 12px; color: #7a5c35; margin-top: 4px; }
.fish-scene { margin: 12px auto 10px; width: 100%; border: 3px solid #4a2c1a; border-radius: 3px; overflow: hidden; background: #35506b; }
#fish-canvas { width: 100%; height: auto; display: block; image-rendering: pixelated; }
.catch-bar {
  position: relative; height: 28px; margin: 0 4px 12px;
  font-family: "Courier New", monospace; font-size: 26px; font-weight: 900;
  color: #4a2c1a; z-index: 9; touch-action: none;
}
#btn-action:active { transform: translateY(5px); box-shadow: 0 0 0 4px #f8eccb, 0 1px 0 #8f5f18; }
body.touch #hotbar { bottom: calc(150px + env(safe-area-inset-bottom, 0px)); }
body.touch #prompt { bottom: calc(250px + env(safe-area-inset-bottom, 0px)); }

/* ---------- Responsive ---------- */
@media (max-width: 720px) {
  #hud-left { width: 232px; gap: 7px; }
  .status-panel { padding: 8px 10px 9px; }
  .date-row { font-size: 12px; }
  #hud-clock { font-size: 16px; }
  #hud-location { display: none; }
  .money-row b { font-size: 15px; }
  #quest-card { padding: 8px 10px; }
  #quest-text { font-size: 11.5px; }
  #hud-right { gap: 5px; }
  .icon-btn { width: 36px; height: 36px; font-size: 15px; }
  #hotbar { gap: 3px; padding: 5px 6px; max-width: calc(100vw - 12px); }
  .hot-slot { width: 46px; height: 55px; }
  .hot-icon { font-size: 18px; }
  .hot-name { font-size: 7px; max-width: 42px; }
  .hot-key { font-size: 8px; }
  .hot-hint { display: none; }
  #prompt { bottom: 92px; font-size: 11px; }
  body.touch #prompt { bottom: 230px; }
  .creation-card { padding: 16px; }
  .create-layout { grid-template-columns: 1fr; justify-items: center; gap: 14px; }
  .create-options { width: 100%; }
  #preview { width: 126px; height: 162px; }
  .dialogue-card { flex-direction: column; align-items: center; text-align: center; }
  .portrait-wrap { flex: 0 0 auto; }
  .dialogue-actions { justify-content: center; }
  #dlg-text { min-height: 0; }
  .shop-card { padding: 14px; max-height: 94vh; }
  .shop-item { gap: 8px; padding: 8px; align-items: flex-start; }
  .shop-item-icon { font-size: 24px; width: 32px; flex-basis: 32px; }
  .shop-item-desc { font-size: 10.5px; }
  .shop-item-buy { max-width: 96px; }
  .shop-item-buy .chip-btn { font-size: 9px; padding: 6px 8px; }
  .shop-money { font-size: 13px; }
  .help-grid { grid-template-columns: 1fr; gap: 12px; }
  .help-card { padding: 16px; }
  .menu-footer { gap: 10px 16px; font-size: 8px; }
  .menu-buttons { gap: 10px; }
  .inv-grid { grid-template-columns: repeat(auto-fill, minmax(122px, 1fr)); }
  #version-tag { display: none; }
}

@media (max-width: 430px) {
  #hud-left { width: 204px; }
  #quest-card { display: block; }
  .icon-btn { width: 33px; height: 33px; font-size: 14px; }
  .hot-slot { width: 42px; height: 50px; }
  .hot-icon { font-size: 16px; }
  .hot-name { display: none; }
  .shop-tabs button { padding: 6px 10px; font-size: 9px; }
  .shop-head h2 { font-size: 17px; }
  .shop-icon { font-size: 28px; }
  .shop-item-buy { max-width: 82px; }
  .catch-bar { height: 24px; }
  #joystick { width: 96px; height: 96px; }
  #joystick-knob { width: 40px; height: 40px; }
  #btn-action { width: 74px; height: 74px; font-size: 22px; }
}

@media (pointer: coarse) {
  #touch-controls { display: block; }
  #hotbar { bottom: calc(150px + env(safe-area-inset-bottom, 0px)); }
  #prompt { bottom: calc(250px + env(safe-area-inset-bottom, 0px)); }
}

